from typing import List

def process_balls_sequence(n: int, input_list: List[int]) -> int:
    sequence = []

    for A_i in input_list:
        size = 2 ** A_i
        sequence.append(size)

        while len(sequence) > 1 and sequence[-1] == sequence[-2]:
            combined_size = sequence.pop() * 2
            sequence.pop()
            sequence.append(combined_size)

    return len(sequence)
